--gray-bg:#F8FAFC;--green:#16c784;--red:#ea3943;--white:#fff;
--border:#e5e7eb;--radius:8px;--font:'Inter',system-ui,-apple-system,sans-serif;
}
html{font-size:16px;-webkit-text-size-adjust:100%}
