arguments.new_string:
/* Layout */
.container{max-width:1400px;margin:0 auto;padding:0 16px}
.full-width{width:100%}

/* Nav */
.nav{background:var(--white);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100}
.nav-inner{display:flex;align-items:center;height:56px;gap:24px}
.nav-logo{font-size:18px;font-weight:700;color:var(--navy);white-space:nowrap}
.nav-logo span{color:var(--blue)}
.nav-links{display:flex;gap:4px;flex:1}
.nav-links a{padding:8px 12px;font-size:14px;font-weight:500;color:var(--navy);border-radius:var(--radius);transition:background .15s}
.nav-links a:hover{background:var(--gray-light);text-decoration:none}
.nav-links a.active{color:var(--blue)}
.nav-right{display:flex;gap:8px;align-items:center;margin-left:auto}
.btn{padding:8px 16px;border-radius:var(--radius);font-size:14px;font-weight:600;transition:all .15s}
.btn-outline{border:1px solid var(--border);color:var(--navy)}
.btn-outline:hover{border-color:var(--blue);color:var(--blue)}
.btn-primary{background:var(--blue);color:var(--white)}
.btn-primary:hover{background:#2d4fd7}

/* Top Metrics Bar */
.metrics-bar{background:var(--white);border-bottom:1px solid var(--border);padding:10px 0;font-size:13px}
.metrics-inner{display:flex;gap:24px;align-items:center;flex-wrap:wrap}
.metric-item{display:flex;align-items:center;gap:6px;white-space:nowrap}
.metric-label{color:var(--gray);font-weight:500}
.metric-value{font-weight:600;color:var(--navy)}
.metric-change{font-weight:600;font-size:12px}
.up{color:var(--green)}.down{color:var(--red)}
.fear-greed{display:inline-flex;align-items:center;gap:4px}
.fear-greed-bar{width:48px;height:6px;border-radius:3px;background:linear-gradient(90deg,var(--red),#f5a623,var(--green));position:relative}
.fear-greed-dot{width:8px;height:8px;border-radius:50%;background:var(--navy);border:2px solid var(--white);position:absolute;top:-1px;transform:translateX(-50%)}

/* Promo Banner */
.promo-banner{background:linear-gradient(135deg,#1a1a2e 0%,#16213e 50%,#0f3460 100%);color:var(--white);overflow:hidden;position:relative}
.promo-track{display:flex;transition:transform .4s ease}
.promo-slide{min-width:100%;padding:12px 0;text-align:center;font-size:14px;font-weight:500}
.promo-slide a{color:#60a5fa;font-weight:600}
.promo-nav{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.15);border:none;color:var(--white);width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:14px;transition:background .15s}
.promo-nav:hover{background:rgba(255,255,255,.3)}
.promo-prev{left:12px}.promo-next{right:12px}

/* AI Alerts */
.ai-bar{background:var(--white);border-bottom:1px solid var(--border);padding:12px 0}
.ai-inner{display:flex;align-items:center;gap:12px;overflow-x:auto;scrollbar-width:none}
.ai-inner::-webkit-scrollbar{display:none}
.ai-topic{font-size:13px;color:var(--navy);font-weight:500;white-space:nowrap;flex-shrink:0}
.ai-chip{padding:6px 14px;border-radius:20px;font-size:12px;color:var(--gray);background:var(--gray-light);white-space:nowrap;cursor:pointer;transition:all .15s;flex-shrink:0;font-weight:500}
.ai-chip:hover{background:var(--blue);color:var(--white)}

/* Section */
.main-content{padding:20px 0}
.section-gap{margin-bottom:24px}

/* Network Tabs */
.network-tabs{display:flex;gap:6px;margin-bottom:16px;flex-wrap:wrap}
.network-tab{padding:6px 14px;border-radius:var(--radius);font-size:13px;font-weight:500;color:var(--gray);background:var(--white);border:1px solid var(--border);cursor:pointer;transition:all .15s}
.network-tab:hover{border-color:var(--blue);color:var(--blue)}
.network-tab.active{background:var(--blue);color:var(--white);border-color:var(--blue)}

/* Category Tabs */
.cat-tabs{display:flex;gap:4px;border-bottom:2px solid var(--border);margin-bottom:16px;overflow-x:auto;scrollbar-width:none}
.cat-tabs::-webkit-scrollbar{display:none}
.cat-tab{padding:10px 16px;font-size:14px;font-weight:500;color:var(--gray);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-2px;white-space:nowrap;transition:all .15s}
.cat-tab:hover{color:var(--navy)}
.cat-tab.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:600}

/* Table Controls */
.table-controls{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px}
.table-controls-left{display:flex;gap:8px;align-items:center}
.control-btn{padding:6px 14px;border-radius:var(--radius);font-size:13px;font-weight:500;color:var(--navy);background:var(--white);border:1px solid var(--border);display:flex;align-items:center;gap:4px;transition:all .15s}
.control-btn:hover{border-color:var(--blue);color:var(--blue)}
.control-btn.active{background:var(--blue);color:var(--white);border-color:var(--blue)}
.control-btn svg{width:14px;height:14px}

/* Index Row */
.index-row{background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:12px 16px;margin-bottom:12px;display:flex;align-items:center;gap:24px;font-size:13px}
.index-name{font-weight:600;color:var(--navy);min-width:240px}
.index-price{font-weight:700;font-variant-numeric:tabular-nums;min-width:100px}
.index-change{font-weight:600;font-variant-numeric:tabular-nums;min-width:70px}

