.table-controls{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px}
.table-controls-left{display:flex;gap:8px;align-items:center}
.control-btn{padding:6px 14px;border-radius:var(--radius);font-size:13px;font-weight:500;color:var(--navy);background:var(--white);border:1px solid var(--border);display:flex;align-items:center;gap:4px;transition:all .15s}
.control-btn:hover{border-color:var(--blue);color:var(--blue)}
.control-btn.active{background:var(--blue);color:var(--white);border-color:var(--blue)}
.control-btn svg{width:14px;height:14px}

