.market-summary{background:var(--white);border-radius:var(--radius);border:1px solid var(--border);padding:20px 24px}
.market-summary h3{font-size:16px;font-weight:700;margin-bottom:8px}
.market-summary p{font-size:14px;color:#4a5568;line-height:1.7}
.market-summary strong{color:var(--navy)}
.read-more-btn{color:var(--blue);font-weight:600;font-size:14px;cursor:pointer;margin-top:8px;display:inline-block}
.read-more-btn:hover{text-decoration:underline}
.summary-extra{display:none;margin-top:8px}
