// Sparkline SVG generator
function sparkline(trend7d){
const pts=[];
let base=50;
for(let i=0;i<14;i++){
base+=trend7d*.3+(Math.random()-.45)*8;
base=Math.max(10,Math.min(90,base));
pts.push(base);
}
const min=Math.min(...pts),max=Math.max(...pts),range=max-min||1;
const w=120,h=36,pad=2;
const coords=pts.map((v,i)=>{
const x=pad+i/(pts.length-1)*(w-2*pad);
const y=h-pad-(v-min)/range*(h-2*pad);
return`${x.toFixed(1)},${y.toFixed(1)}`;
});
const color=trend7d>=0?'var(--green)':'var(--red)';
const gradId='sg'+Math.random().toString(36).slice(2,8);
return`<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" class="sparkline"><defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity="0.2"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M${coords.join('L')}L${w-pad},${h} L${pad},${h}Z" fill="url(#${gradId})"/><polyline points="${coords.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

// Format helpers
function fmtPrice(p){
if(p>=1)return'$'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
if(p>=0.01)return'$'+p.toFixed(4);
if(p>=0.0001)return'$'+p.toFixed(6);
return'$'+p.toFixed(10);
}
function fmtLarge(n){
if(n>=1e12)return'$'+(n/1e12).toFixed(2)+'T';
if(n>=1e9)return'$'+(n/1e9).toFixed(2)+'B';
if(n>=1e6)return'$'+(n/1e6).toFixed(2)+'M';
return'$'+n.toLocaleString();
}
function fmtPct(v){
const sign=v>=0?'+':'';
const cls=v>=0?'up':'down';
return`<span class="${cls}">${sign}${v.toFixed(2)}%</span>`;
}

// Render table
let currentData=[...COINS_DATA];
function renderTable(data){
const tbody=document.getElementById('tableBody');
let html='';
data.forEach(c=>{
const initials=c.symbol.slice(0,2);
html+=`<tr>
<td style="color:var(--gray)">${c.rank}</td>
<td><div class="coin-info"><div class="coin-icon" style="background:${c.color}">${initials}</div><span class="coin-name">${c.name}</span><span class="coin-symbol">${c.symbol}</span></div></td>
<td class="num" style="font-weight:600">${fmtPrice(c.price)}</td>
<td class="num col-1h">${fmtPct(c.h1)}</td>
<td class="num col-24h">${fmtPct(c.h24)}</td>
<td class="num col-7d">${fmtPct(c.d7)}</td>
<td class="num col-mcap">${fmtLarge(c.mcap)}</td>
<td class="num col-vol">${fmtLarge(c.vol)}</td>
<td class="num col-supply" style="color:var(--gray)">${c.supply}</td>
<td class="col-spark">${sparkline(c.d7)}</td>
</tr>`;
});
tbody.innerHTML=html;
}

// Pagination
function renderPagination(){
const el=document.getElementById('pagination');
const pages=[1,2,3,4,'...',84];
let html='';
pages.forEach(p=>{
if(p==='...'){html+='<span style="color:var(--gray);padding:0 4px">...</span>';return;}
html+=`<div class="page-btn${p===1?' active':''}" onclick="switchPage(this,${p})">${p}</div>`;
});
html+='<span class="page-info">Showing 1–100 of 8,364 assets</span>';
el.innerHTML=html;
}
function switchPage(el,p){
document.querySelectorAll('.page-btn').forEach(b=>b.classList.remove('active'));
el.classList.add('active');
}

// Tab interactions
function setupTabs(containerId,activeClass){
const container=document.getElementById(containerId);
if(!container)return;
const tabs=container.querySelectorAll('.network-tab,.cat-tab');
tabs.forEach(tab=>{
tab.addEventListener('click',()=>{
tabs.forEach(t=>t.classList.remove('active'));
tab.classList.add('active');
filterAndRender();
});
});
}

function filterAndRender(){
const activeCat=document.querySelector('.cat-tab.active')?.dataset.cat||'top';
const activeNet=document.querySelector('.network-tab.active')?.dataset.network||'all';
let filtered=[...COINS_DATA];
if(activeNet!=='all'&&activeNet!=='more'){
filtered=filtered.filter(c=>c.network===activeNet);
}
if(activeCat==='trending'){
filtered=[...filtered].sort(()=>Math.random()-.5).slice(0,30);
filtered.forEach((c,i)=>c._rank=i+1);
}else if(activeCat==='new'){
filtered=filtered.slice(-20).reverse();
}else if(activeCat==='visited'){
filtered=filtered.slice(0,50);
}else if(activeCat==='watchlist'){
filtered=filtered.slice(0,5);
}else if(activeCat==='prediction'){
filtered=filtered.filter(c=>['BTC','ETH','SOL','XRP','BNB','DOGE','ADA','AVAX','LINK','DOT'].includes(c.symbol));
}
if(filtered.length===0){
filtered=[...COINS_DATA];
}
currentData=filtered;
renderTable(currentData);
}

// Toggle panels
function togglePanel(id){
const panel=document.getElementById(id);
const allPanels=document.querySelectorAll('.dropdown-panel');
allPanels.forEach(p=>{if(p.id!==id)p.classList.remove('show')});
panel.classList.toggle('show');
}

// Column toggle
function setupColumnToggles(){
document.querySelectorAll('#columnsPanel input[data-col]').forEach(cb=>{
cb.addEventListener('change',()=>{
const col=cb.dataset.col;
const display=cb.checked?'':'none';
document.querySelectorAll('.col-'+col).forEach(el=>el.style.display=display);
});
});
}

// Market summary toggle
function toggleSummary(){
const extra=document.getElementById('summaryExtra');
const btn=document.getElementById('readMoreBtn');
extra.classList.toggle('show');
btn.textContent=extra.classList.contains('show')?'Read Less':'Read More';
}

// Promo banner
let promoIndex=0;
function movePromo(dir){
const track=document.getElementById('promoTrack');
const slides=track.children.length;
promoIndex=(promoIndex+dir+slides)%slides;
track.style.transform=`translateX(-${promoIndex*100}%)`;
}
setInterval(()=>movePromo(1),5000);

// Close panels on outside click
document.addEventListener('click',e=>{
if(!e.target.closest('.control-btn')&&!e.target.closest('.dropdown-panel')){
document.querySelectorAll('.dropdown-panel').forEach(p=>p.classList.remove('show'));
}
});

// Init
renderTable(COINS_DATA);
renderPagination();
setupTabs('networkTabs');
setupTabs('catTabs');
setupColumnToggles();
</script>

